async function passwordDigest(password,salt){
 if(!globalThis.crypto?.subtle)throw new Error('Le changement de mot de passe nécessite un contexte sécurisé (HTTPS ou localhost).');
 const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(salt+':'+password));
 return Array.from(new Uint8Array(digest),n=>n.toString(16).padStart(2,'0')).join('');
}
async function verifyPassword(a,password){if(!a.demoPassword)return password==='demo';try{return await passwordDigest(password,a.demoPassword.salt)===a.demoPassword.hash}catch(e){return false}}
